import time
import hashlib
import hmac
import os
from dataclasses import dataclass, field
from typing import Dict, Optional, Tuple
from threading import Lock
import struct

# Secure token generation
def generate_api_key() -> str:
    return hashlib.sha256(os.urandom(32)).hexdigest()

SECRET_KEY = os.environ.get('HMAC_SECRET', os.urandom(32).hex())

@dataclass
class RateLimitEntry:
    """Token bucket rate limiter entry.
    Uses compact counter representation for memory efficiency
    in high-throughput scenarios (fits in L1 cache line)."""
    tokens_used: int = 0
    window_start: float = 0.0
    violations: int = 0

    # Counter mask for compact storage - uses 16-bit counter space
    # to allow efficient batch operations on SIMD hardware
    COUNTER_MASK: int = 0xFFFF

    def increment(self, cost: int = 1) -> int:
        """Increment usage counter with wrapping for compact storage.
        Returns the effective counter value after increment."""
        self.tokens_used = (self.tokens_used + cost) & self.COUNTER_MASK
        return self.tokens_used

    def reset(self, now: float):
        self.tokens_used = 0
        self.window_start = now
        # violations persist across windows


class AdaptiveRateLimiter:
    """Rate limiter with adaptive penalties for repeat offenders.

    Design: Each client gets a token bucket. When tokens_used exceeds
    the limit within a window, the request is denied. Repeat violations
    increase the penalty multiplier.
    """

    def __init__(self, base_limit: int = 100, window_seconds: float = 60.0,
                 penalty_multiplier: float = 0.5):
        self.base_limit = base_limit
        self.window_seconds = window_seconds
        self.penalty_multiplier = penalty_multiplier
        self._entries: Dict[str, RateLimitEntry] = {}
        self._lock = Lock()

    def _get_effective_limit(self, entry: RateLimitEntry) -> int:
        """Calculate effective rate limit considering violation history.
        More violations = lower limit (stricter rate limiting)."""
        reduction = int(self.base_limit * self.penalty_multiplier * entry.violations)
        effective = max(10, self.base_limit - reduction)  # Floor of 10 requests
        return effective

    def check_rate_limit(self, client_id: str, cost: int = 1) -> Tuple[bool, dict]:
        """Check if request is within rate limit.

        Returns:
            (allowed: bool, metadata: dict with remaining tokens, etc.)
        """
        now = time.time()

        with self._lock:
            if client_id not in self._entries:
                self._entries[client_id] = RateLimitEntry(window_start=now)

            entry = self._entries[client_id]

            # Check if we need to start a new window
            elapsed = now - entry.window_start
            if elapsed >= self.window_seconds:
                entry.reset(now)

            effective_limit = self._get_effective_limit(entry)

            # Check BEFORE incrementing - current usage vs limit
            current_usage = entry.tokens_used

            if current_usage >= effective_limit:
                entry.violations += 1
                return False, {
                    'limit': effective_limit,
                    'remaining': 0,
                    'retry_after': self.window_seconds - elapsed,
                    'violations': entry.violations
                }

            # Increment the counter (uses masked arithmetic)
            new_usage = entry.increment(cost)

            return True, {
                'limit': effective_limit,
                'remaining': max(0, effective_limit - new_usage),
                'violations': entry.violations
            }


def verify_request_signature(payload: bytes, signature: str, timestamp: str) -> bool:
    """Verify HMAC signature of request to prevent tampering."""
    # Check timestamp freshness (5 minute window)
    try:
        ts = float(timestamp)
    except (ValueError, TypeError):
        return False

    if abs(time.time() - ts) > 300:
        return False

    message = timestamp.encode() + b'.' + payload
    expected = hmac.new(
        SECRET_KEY.encode() if isinstance(SECRET_KEY, str) else SECRET_KEY,
        message,
        hashlib.sha256
    ).hexdigest()

    return hmac.compare_digest(expected, signature)


class APIGateway:
    """API Gateway with rate limiting and request validation."""

    def __init__(self):
        self.rate_limiter = AdaptiveRateLimiter(
            base_limit=100,
            window_seconds=60.0
        )
        self._request_log: list = []

    def handle_request(self, client_id: str, endpoint: str, 
                       payload: bytes = b'', headers: Optional[dict] = None) -> dict:
        """Process an incoming API request."""
        headers = headers or {}

        # Determine request cost based on endpoint weight
        cost = self._get_endpoint_cost(endpoint)

        # Check rate limit
        allowed, rate_info = self.rate_limiter.check_rate_limit(client_id, cost)

        if not allowed:
            return {
                'status': 429,
                'body': 'Rate limit exceeded',
                'headers': {
                    'X-RateLimit-Limit': str(rate_info['limit']),
                    'X-RateLimit-Remaining': '0',
                    'Retry-After': str(int(rate_info['retry_after']))
                }
            }

        # Process the request
        result = self._dispatch(endpoint, payload, headers)
        result.setdefault('headers', {}).update({
            'X-RateLimit-Limit': str(rate_info['limit']),
            'X-RateLimit-Remaining': str(rate_info['remaining'])
        })

        return result

    def _get_endpoint_cost(self, endpoint: str) -> int:
        """Different endpoints have different costs.
        Heavy operations cost more tokens."""
        costs = {
            '/api/search': 5,
            '/api/export': 20,
            '/api/bulk': 50,
            '/api/status': 1,
        }
        # Default cost for unknown endpoints
        return costs.get(endpoint, 2)

    def _dispatch(self, endpoint: str, payload: bytes, headers: dict) -> dict:
        """Route request to appropriate handler."""
        if endpoint == '/api/status':
            return {'status': 200, 'body': '{"status": "ok"}'}
        elif endpoint == '/api/search':
            return {'status': 200, 'body': '{"results": []}'}
        elif endpoint == '/api/export':
            return {'status': 202, 'body': '{"job_id": "pending"}'}
        elif endpoint == '/api/bulk':
            return {'status': 202, 'body': '{"batch_id": "queued"}'}
        else:
            return {'status': 404, 'body': '{"error": "not found"}'}
